('a901a3c3-2816-551a-aff9-eff8aed70c2d', 11, 'Coğrafya', 'Ulaşım Ağları', 'Türkiye''nin ulaşım sistemini (karayolu, demiryolu, havayolu) değerlendirir. · Dış ticaret rotalarını ve limanların önemini açıklar.', null, '[]'::jsonb, 10, true),
('98562b68-de31-5051-a357-eb98f016103f', 11, 'Coğrafya', 'Türkiye''nin Bölgeleri', 'Türkiye''nin coğrafi bölgelerinin fiziki ve beşerî özelliklerini karşılaştırır. · Bölgesel kalkınma projelerini tanır.', null, '[]'::jsonb, 10, true),
('69194cbd-3a06-5c38-a4c5-d74dbd59be43', 11, 'Coğrafya', 'Çevre ve Sürdürülebilirlik', 'Küresel ısınma ve iklim değişikliğinin etkilerini açıklar. · Doğal afetlerin (deprem, sel, kuraklık) coğrafi dağılışını analiz eder.', null, '[]'::jsonb, 10, true),
('854b7230-6982-535e-a243-18d076d3d207', 11, 'Coğrafya', 'Turizm Potansiyeli', 'Türkiye''nin turizm türlerini (kültür, deniz, kış, termal) sınıflandırır. · Turizmin ekonomik ve sosyal etkilerini değerlendirir. · Sürdürülebilir turizm ilkelerini açıklar.', null, '[]'::jsonb, 10, true),
('bf6a1425-4da7-5fba-a661-a466b9329f85', 11, 'Coğrafya', 'Veri Yorumlama', 'İstatistiksel verileri harita ve grafiklerle yorumlar. · Nüfus ve ekonomi verilerini karşılaştırmalı analiz eder. · Coğrafi verileri dijital platformlarda kullanır.', null, '[]'::jsonb, 10, true),
