('764f3120-93f4-5b17-a873-5e446726f41c', 1, 'Matematik', 'Uzunluk Ölçme', 'Nesnelerin uzunluklarını standart olmayan birimlerle karşılaştırır ve sıralar.', null, '[]'::jsonb, 10, true),
('4889853b-7a17-5bc8-af81-8c8abcf8b385', 1, 'Matematik', 'Paralarımız', 'Günlük hayatta kullanılan paraları tanır ve basit miktarları karşılaştırır.', null, '[]'::jsonb, 10, true),
('49b27b9f-e773-5f4e-a2e9-336fbc8e1ee8', 1, 'Matematik', 'Zaman Ölçme', 'Tam ve yarım saatleri analog saatte okur. · Günü, haftayı ve ayı belirtir. · Olayları önce-sonra, bugün-dün-yarın, sabah-öğle-akşam gibi ifadelerle sıralar.', null, '[]'::jsonb, 10, true),
('4bca7712-aebc-5b73-a525-cc498162c8bc', 1, 'Matematik', 'Tartma', 'Nesneleri ağırlık-hafiflik bakımından karşılaştırır.', null, '[]'::jsonb, 10, true),
('bc250ae2-1049-5baf-a79d-356d5574eed8', 1, 'Matematik', 'Sıvı Ölçme', 'Kaplardaki sıvı miktarlarını azlık-çokluk bakımından karşılaştırır.', null, '[]'::jsonb, 10, true),
('fe211660-ad94-5447-a1ce-d9e0b8cd890d', 1, 'Matematik', 'Veri Toplama ve Değerlendirme', 'Basit sorularla veri toplar; nesne veya şekil grafiğiyle gösterir.', null, '[]'::jsonb, 10, true),
('3b211310-5df0-55ed-a42b-0a3148514d1a', 1, 'Türkçe', 'Dinlenen / İzlenen Metni Anlama', 'Dinlediği / izlediği kısa metindeki kişi, yer ve olayları ayırt eder. · Dinlediği / izlediği metnin konusunu basit düzeyde belirler. · Dinlediği / izlediği metne yönelik basit sorulara cevap verir. · Dinlediklerini / izlediklerini kendi cümleleriyle anlatır.', null, '[]'::jsonb, 10, true),
('1568861c-db3f-566e-ab94-7e776a45ff36', 1, 'Türkçe', 'Söz Varlığı', 'Dinlediği metindeki yeni kelimeleri fark eder ve anlamını sorar. · Görsellerle dinlenen içerik arasında bağ kurar.', null, '[]'::jsonb, 10, true),
('94baddb6-8dc2-5e48-ab34-6fa5d515f06e', 1, 'Türkçe', 'Sözlü İfade', 'Kendini, ailesini ve yakın çevresini kısa cümlelerle tanıtır. · Günlük olayları sırayla anlatır. · Konuşurken nezaket ifadelerini kullanır. · Soru sorar ve sorulara cevap verir.', null, '[]'::jsonb, 10, true),
('d2614746-7333-5d5e-a88d-f83495ee3be0', 1, 'Türkçe', 'Okumaya Hazırlık ve İlk Okuma', 'Sesleri tanır, harflerle eşleştirir. · Hece, kelime ve kısa cümleleri okur. · Kısa metinleri sesli ve anlaşılır okur.', null, '[]'::jsonb, 10, true),
('4a66342d-e31b-5b6f-ad22-67460fc4483b', 1, 'Türkçe', 'Okuduğunu Anlama', 'Okuduğu kısa metindeki kişileri ve olayları belirler. · Okuduğu metne yönelik basit sorulara cevap verir. · Görsellerle okunan metin arasında ilişki kurar.', null, '[]'::jsonb, 10, true),
('922c75a0-42bc-5810-a6ae-ebff90e3f571', 1, 'Türkçe', 'Sözcük Dağarcığı', 'Eş ve zıt anlamlı basit kelime çiftlerini fark eder.', null, '[]'::jsonb, 10, true),
('dc4ad3f8-9c0f-50b4-ac7d-b66257808f15', 1, 'Türkçe', 'Yazmaya Hazırlık ve Yazma', 'Harfleri doğru biçim ve yönde yazar. · Hece, kelime ve kısa cümleler yazar. · Cümleye büyük harfle başlar, nokta koyar. · Kısa bir not veya kartpostal yazar.', null, '[]'::jsonb, 10, true),
('22b1d956-7379-5e6b-aa90-794242c98f40', 1, 'Türkçe', 'Ses, Harf ve Cümle', 'Türk alfabesindeki harfleri tanır. · Anlamlı kısa cümleler kurar. · Tekil-çoğul ve soru ifadelerini basit düzeyde kullanır.', null, '[]'::jsonb, 10, true),
('2ad994eb-c09b-59b4-aff5-03431482d7fe', 1, 'Türkçe', 'Noktalama', 'Nokta ve soru işaretini yerinde kullanır.', null, '[]'::jsonb, 10, true),
('7752fcec-bc08-570a-ade2-53c4db6f6cd3', 1, 'Türkçe', 'Ben ve Okulum', 'Okul ve ben temalı metinlerde kendini ve çevresini tanır.', null, '[]'::jsonb, 10, true),
('61e41540-2ac4-5083-a54f-4bd1e02bb0b3', 1, 'Türkçe', 'Değerlerimiz', 'Sevgi, saygı ve yardımlaşma mesajlarını metinden fark eder.', null, '[]'::jsonb, 10, true),
('74e4e0e8-233c-53d9-af02-85928356047a', 1, 'Türkçe', 'Atatürk', 'Atatürk’le ilgili yaş düzeyine uygun kısa metinleri anlar.', null, '[]'::jsonb, 10, true),
('6599e10d-9157-51fb-aa99-f9858f5ddfee', 1, 'Türkçe', 'Doğa', 'Doğa ve hayvan temalı metinlerde temel bilgileri belirler.', null, '[]'::jsonb, 10, true),
('6a9c87ee-f366-5e1a-acf4-651df73b267e', 1, 'Türkçe', 'Sağlık', 'Temizlik ve sağlıklı yaşam temalı kısa metinleri anlar.', null, '[]'::jsonb, 10, true),
('b0213e1a-00e1-510b-a0a3-bc71d3959554', 2, 'Hayat Bilgisi', 'Duygularım', 'Duygularını tanır ve uygun ifade yollarını kullanır. · Arkadaşlık ilişkilerinde empati gösterir.', null, '[]'::jsonb, 10, true),
('7337a750-9220-5d3c-aab8-e0098253932e', 2, 'Hayat Bilgisi', 'Hareket ve Dinlenme', 'Günlük hareket ve dinlenme dengesinin önemini açıklar. · Tehlikeli maddelerden uzak durma kurallarını bilir.', null, '[]'::jsonb, 10, true),
